export type ElectricAssemblyId = 'frame' | 'fretboard' | 'nut' | 'tuners' | 'pickups' | 'bridge' | 'controls' | 'strings';
type Point = readonly [number, number, number];

export interface ElectricAssembly {
  id: ElectricAssemblyId;
  name: string;
  info: string;
  order: number;
  offset: Point;
}

