/** Bounds are in the fixed recovered mesh's original coordinate system. */
export function electricComponentAssembly(bounds: { min: Point; max: Point }): ElectricAssemblyId {
  const size = bounds.max.map((value, axis) => value - bounds.min[axis]);
  const x = (bounds.min[0] + bounds.max[0]) / 2, z = (bounds.min[2] + bounds.max[2]) / 2;
  if (![...bounds.min, ...bounds.max].every(Number.isFinite) || size.some(value => value < 0)) {
    throw new Error('Invalid recovered assembly bounds.');
  }
  if (size[0] > .95 || x > .12 || (x < -.30 && z < -.10)) return 'frame';
  if (size[0] > .6 && size[2] < .04) return 'strings';
  if (size[0] > .45 && size[2] > .04 && size[1] < .01) return 'fretboard';
  if (x < -.735) return 'tuners';
  if (x < -.69) return 'nut';
  if (x < -.185 && Math.abs(z) < .05) return 'fretboard';
  if (x > -.20 && x < -.055 && size[0] > .03 && bounds.min[2] > -.055 && bounds.max[2] < .055) return 'pickups';
  if (x > -.03 && x < .055 && z > .055 && size[2] < .03) return 'controls';
  if (bounds.min[0] > -.09 && bounds.max[0] < .12) return 'bridge';
  throw new Error(`Unrecognized recovered electric component at ${x.toFixed(4)}, ${z.toFixed(4)}.`);
}

export function electricAssemblyProgress(assembly: ElectricAssembly, amount: number): number {
  if (!Number.isFinite(amount) || amount < 0 || amount > 1) throw new RangeError('Disassembly must be between zero and one.');
  if (assembly.order === 0) return 0;
  const start = (7 - assembly.order) * .065;
  const progress = Math.max(0, Math.min(1, (amount - start) / (1 - start)));
  return progress < .5 ? 4 * progress ** 3 : 1 - (-2 * progress + 2) ** 3 / 2;
}

export function electricAssemblyOffset(assembly: ElectricAssembly, amount: number): [number, number, number] {
  const progress = electricAssemblyProgress(assembly, amount);
  return progress === 0 ? [0, 0, 0] : [
    assembly.offset[0] * progress, assembly.offset[1] * progress, assembly.offset[2] * progress,
  ];
}
